#!/usr/bin/env python3
"""Review-only CEFR candidate risk triage; NEVER classifies proficiency definitively.

This audit finds likely candidate-pool problems before editorial work. It does
not change the candidate lists, copy dictionary content, or approve translations.
"""
import collections
import json
import re
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
TARGETS={"A1":500,"A2":700,"B1":1000,"B2":1300,"C1":1500}
# This curated set is NOT an exhaustive word filter; it flags especially risky
# first-WordNet-sense examples seen in the autogenerated shortlist.
KNOWN_SENSE_RISKS={
    "let":"WordNet's first lemma may refer to a named militant acronym rather than the verb",
    "it's":"WordNet's lexical clue may be information technology rather than the contraction",
    "he's":"WordNet's lexical clue may be a chemical element rather than the contraction",
    "us":"WordNet's clue may be the United States abbreviation instead of object pronoun",
    "s":"Single-letter abbreviation requiring POS and context check",
    "k":"Single-letter abbreviation requiring POS and context check",
    "da":"Ambiguous abbreviation; not necessarily a learner headword",
    "mr":"Abbreviation for a form of address",
    "pc":"Technical abbreviation; uncertain level",
    "pussy":"Multiple register-sensitive meanings, including adult slang; requires age-appropriate editorial decision",
}
# Likely named entities (not an exhaustive geographic/personal-name index).
NAMED_ENTITY_WORDS={"russia","africa","trump","michigan","manchester","stewart",
                    "albert","harvard","marshall","mitchell","nelson","poland"}
LEVELS=("A1","A2","B1","B2","C1")

def audit(data,drafts,evidence):
    rows=data.get("entries",[])
    if data.get("release_status")!="UNVERIFIED_DRAFT_DO_NOT_PUBLISH":
        raise ValueError("Source candidates must remain unverified")
    if len(rows)!=5000 or len({x.get("word") for x in rows})!=5000:
        raise ValueError("Invalid candidate count or duplicate words")
    counts=collections.Counter(x.get("level") for x in rows)
    if counts!=collections.Counter(TARGETS):
        raise ValueError("CEFR planning quotas have changed")
    if drafts.get("release_status")!="UNVERIFIED_DRAFT_DO_NOT_PUBLISH":
        raise ValueError("Drafts must be unapproved")
    if evidence.get("release_status")!="UNVERIFIED_DRAFT_DO_NOT_PUBLISH":
        raise ValueError("Source observations must be unapproved")
    reviewed={x.get("word") for x in drafts.get("entries",[])}
    observed={x["word"]:x for x in evidence.get("records",[])}
    if len(reviewed)!=len(drafts.get("entries",[])) or len(observed)!=len(evidence.get("records",[])):
        raise ValueError("Duplicate review rows")
    by_reason=collections.Counter()
    by_level=collections.Counter()
    samples={name:[] for name in TARGETS}
    flagged=[]
    for row in rows:
        word=row.get("word","")
        level=row.get("level")
        first_sense=row.get("english_definition_draft","")
        reasons=[]
        if level=="A1":
            continue
        if word in KNOWN_SENSE_RISKS:
            reasons.append("KNOWN_FIRST_SENSE_OR_REGISTER_MISMATCH")
        if word in NAMED_ENTITY_WORDS:
            reasons.append("LIKELY_PROPER_NOUN_IN_GENERAL_LEARNER_LIST")
        if "'" in word:
            reasons.append("CONTRACTION_REQUIRES_WORD_FORM_REVIEW")
        if len(word)<=2:
            reasons.append("SHORT_ABBREVIATION_OR_FUNCTION_WORD_REVIEW")
        if len(word)>4 and re.search(r"(?:ing|ed|s)$",word):
            reasons.append("MORPHOLOGICAL_FORM_NEEDS_LEMMA_CHECK")
        if level=="C1" and isinstance(row.get("zipf_frequency"),(int,float)) and row["zipf_frequency"]>=4.0:
            reasons.append("FREQUENT_C1_HEADWORD_RECHECK")
        if word in observed and observed[word].get("provisional_level_conflicts_with_source"):
            reasons.append("DOCUMENTED_SOURCE_CEFR_LEVEL_CONFLICT")
        if not reasons:
            continue
        by_level[level]+=1
        for reason in reasons:by_reason[reason]+=1
        flagged.append({
          "word":word,"level_provisional":level,
          "frequency_zipf":row.get("zipf_frequency"),
          "first_wordnet_sense_clue_not_approved":first_sense,
          "reasons":sorted(set(reasons)),
          "original_draft_exists":word in reviewed,
          "source_observation_exists":word in observed,
          "editorial_approval":False,
        })
        if len(samples[level])<20:
            samples[level].append({"word":word,"reasons":sorted(set(reasons))})
    summary={
       "status":"EDITORIAL_TRIAGE_NOT_RELEASE_APPROVAL",
       "source_headwords":len(rows),
       "a2_c1_candidate_count":4500,
       "a2_c1_first_draft_count":sum(x["level"]!="A1" for x in drafts["entries"]),
       "flagged_review_rows":len(flagged),
       "flag_counts_by_reason":dict(sorted(by_reason.items())),
       "flag_counts_by_level":dict(sorted(by_level.items())),
       "examples_by_level":samples,
       "needs_editorial_sense_and_level_review":flagged,
       "release_ready":False,
       "disclaimer":"Heuristic flags are not independent linguistic verification. Unflagged entries are also NOT approved.",
    }
    return summary

def main():
    source=json.loads((ROOT/"draft/UNVERIFIED_CEFR_CANDIDATES.json").read_text("utf8"))
    drafts=json.loads((ROOT/"draft/A2-C1-EDITORIAL-STARTER.json").read_text("utf8"))
    evidence=json.loads((ROOT/"draft/A2-C1-SOURCE-EVIDENCE-REVIEW.json").read_text("utf8"))
    report=audit(source,drafts,evidence)
    outfile=ROOT/"scratch/CEFR-HEURISTIC-CANDIDATE-TRIAGE.json"
    outfile.parent.mkdir(parents=True,exist_ok=True)
    outfile.write_text(json.dumps(report,ensure_ascii=False,indent=2)+"\n","utf8")
    print("A2-C1 candidate review pool:",report["a2_c1_candidate_count"])
    print("First bilingual drafts still unverified:",report["a2_c1_first_draft_count"])
    print("Heuristic flags for manual review:",report["flagged_review_rows"])
    print("Issue categories:",json.dumps(report["flag_counts_by_reason"],sort_keys=True))
    for level in ("A2","B1","B2","C1"):
        print(level,"sample:",", ".join(x["word"] for x in report["examples_by_level"][level][:12]))
    print("PASS: generated prioritised review queue. NO vocabulary certified or published.")

if __name__=="__main__":
    main()
